-- Analytics queries for Movie Reviews ETL Pipeline\n-- These queries provide insights from the cleaned data\n\n-- Query 1: Top 10 rated movies\nSELECT movie_title, AVG(rating) as avg_rating, COUNT(*) as review_count\nFROM `movie_reviews_db.cleaned_reviews`\nGROUP BY movie_title\nORDER BY avg_rating DESC\nLIMIT 10;\n\n-- Query 2: Rating distribution\nSELECT rating_category, COUNT(*) as count\nFROM `movie_reviews_db.cleaned_reviews`\nGROUP BY rating_category;\n\n-- Query 3: Movie statistics\nSELECT movie_title, AVG(rating) as avg_rating, COUNT(*) as reviews\nFROM `movie_reviews_db.cleaned_reviews`\nGROUP BY movie_title\nHAVING COUNT(*) > 5;\n\n-- Query 4: Reviews by year\nSELECT EXTRACT(YEAR FROM release_date) as year, COUNT(*) as review_count\nFROM `movie_reviews_db.cleaned_reviews`\nGROUP BY year\nORDER BY year;
